/// <summary>
/// <c>TelemetryDataManagementImport</c> class log monitoring and telemetry custom events/metrics
/// </summary>
internal final class METTelemetryDataManagementImport extends METTelemetryBase
{
    private DMFDefinitionGroupExecutionHistory  dmfDefinitionGroupExecutionHistory;
    private TransDateTime                       executionStartTime;
    private TransDateTime                       executionEndTime;
}

Method.Source:
void new(TransDateTime _operationStart, TransDateTime _operationEnd,DMFDefinitionGroupExecutionHistory _dmfDefinitionGroupExecutionHistory)
{
    super();
    dmfDefinitionGroupExecutionHistory = _dmfDefinitionGroupExecutionHistory;
    executionStartTime = _operationStart;
    executionEndTime = _operationEnd;
}

/// <summary>
/// populate telemetry entries to a map
/// </summary>
protected void populateProperties()
{
    // We don't have to call the SetElapsedMilliSeconds() because we are getting the execution time from the table entry
    // this.setElapsedMilliseconds();
    this.addBaseProperty(METApplicationInsightsEventProperties::ElapsedMilliseconds, int642Str(DateTimeUtil::getDifference(executionEndTime, executionStartTime)));
    this.addBaseProperty(METApplicationInsightsEventProperties::DefinitionGroup, dmfDefinitionGroupExecutionHistory.DefinitionGroup);
    this.addBaseProperty(METApplicationInsightsEventProperties::Entity, dmfDefinitionGroupExecutionHistory.Entity);
    this.addBaseProperty(METApplicationInsightsEventProperties::ExecutionId,dmfDefinitionGroupExecutionHistory.ExecutionId);
    this.addBaseProperty(METApplicationInsightsEventProperties::NoOfRecords, int2Str(dmfDefinitionGroupExecutionHistory.NoOfRecords));
    this.addBaseProperty(METApplicationInsightsEventProperties::NumOfTargetNew,int2Str(dmfDefinitionGroupExecutionHistory.NumOfTargetNew));
    this.addBaseProperty(METApplicationInsightsEventProperties::NumOfTargetUpdated, int2Str(dmfDefinitionGroupExecutionHistory.NumOfTargetUpdated));
}
